using System;using System.IO;using System.Linq;using System.Threading.Tasks;using System.Windows.Forms;using System.Web.Script.Serialization;using Microsoft.Web.WebView2.Core;
internal static class RealPdfSelectionAcceptance {
 static JavaScriptSerializer json=new JavaScriptSerializer();static CoreWebView2 browser;
 static async Task Wait(string condition){for(int i=0;i<200;i++){if(await browser.ExecuteScriptAsync(condition)=="true")return;await Task.Delay(100);}throw new Exception("Timed out "+condition);}
 [STAThread]static void Main(string[] args){string repo=Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"../../../.."));Directory.SetCurrentDirectory(repo);if(args.Length==0){args=new[]{File.ReadAllText("work/actual-selection-path.txt").Trim()};Console.SetOut(new StreamWriter("work/real-selection-test.log",false){AutoFlush=true});}string folder=Path.GetFullPath("work/real-selection-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);ModernUi.Enabled=true;ModernUi.AssetsOverride=Path.GetFullPath("ui/dist");ModernUi.UserDataOverride=Path.Combine(folder,"profile");DocumentDataRepository.DataRootOverride=Path.Combine(folder,"data");Application.EnableVisualStyles();var form=new PdfReaderForm(args);var timer=new Timer{Interval=400};timer.Tick+=async delegate{timer.Stop();try{for(int i=0;i<100&&!form.UsesModernUi;i++)await Task.Delay(100);browser=form.ModernBrowser.CoreWebView2;await Wait("document.querySelectorAll('[data-page=\"0\"] .pdf-text-word').length>5");
 var previousClipboard=new DataObject();var clipboard=Clipboard.GetDataObject();if(clipboard!=null)foreach(string format in clipboard.GetFormats(false)){var value=clipboard.GetData(format,false);if(value is MemoryStream)value=new MemoryStream(((MemoryStream)value).ToArray());if(value!=null)previousClipboard.SetData(format,false,value);}try{foreach(int page in new[]{0,20}){await browser.ExecuteScriptAsync("window.chrome.webview.postMessage({op:'goto',page:"+page+"})");await Task.Delay(400);await Wait("document.querySelectorAll('[data-page=\""+page+"\"] .pdf-text-word').length>2");await browser.ExecuteScriptAsync("document.querySelector('[data-page=\""+page+"\"]').scrollIntoView({block:'start',inline:'nearest'})");await Task.Delay(350);var point=json.Deserialize<double[]>(await browser.ExecuteScriptAsync("(()=>{let v=document.querySelector('.reader-scroll').getBoundingClientRect(),e=[...document.querySelectorAll('[data-page=\""+page+"\"] .pdf-text-word')].find(e=>{let r=e.getBoundingClientRect();return r.top>v.top+10&&r.bottom<v.bottom&&r.left>v.left&&r.right<v.right;});let r=e.getBoundingClientRect();return [r.left+r.width*.5,r.top+r.height*.5]})()"));using(var shot=File.Create(Path.Combine(folder,"before-"+page+".png")))await browser.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,shot);foreach(string kind in new[]{"mousePressed","mouseReleased"})await browser.CallDevToolsProtocolMethodAsync("Input.dispatchMouseEvent",json.Serialize(new{type=kind,x=point[0],y=point[1],button="left",buttons=kind=="mousePressed"?1:0,clickCount=2}));await Wait("window.getSelection().toString().trim().length>0");Console.WriteLine("PASS actual PDF page "+page+" double-click selects visible text");var selected=json.Deserialize<string>(await browser.ExecuteScriptAsync("window.getSelection().toString()"));await browser.ExecuteScriptAsync("window.chrome.webview.postMessage({op:'copyText',text:"+json.Serialize(selected)+"})");for(int retry=0;retry<50&&Clipboard.GetText()!=selected;retry++)await Task.Delay(100);if(Clipboard.GetText()!=selected)throw new Exception("Clipboard mismatch");Console.WriteLine("PASS actual PDF page "+page+" copy matches selected Chinese text");foreach(string kind in new[]{"mousePressed","mouseMoved","mouseReleased"})await browser.CallDevToolsProtocolMethodAsync("Input.dispatchMouseEvent",json.Serialize(new{type=kind,x=point[0]+(kind=="mousePressed"?0:24),y=point[1],button="left",buttons=kind=="mouseReleased"?0:1,clickCount=1}));await Wait("window.getSelection().toString().trim().length>0");Console.WriteLine("PASS actual PDF page "+page+" drag selects visible text");using(var stream=File.Create(Path.Combine(folder,"selection-"+page+".png")))await browser.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,stream);}
 }finally{Clipboard.SetDataObject(previousClipboard,true,20,100);}Console.WriteLine("REAL_PDF_SELECTION_PASS "+folder);form.Close();}catch(Exception e){Console.WriteLine(e);Environment.Exit(1);}};form.Shown+=delegate{timer.Start();};Application.Run(form);}
}
